select jsonb_build_object('checked_at',now(),'suppliers',(select count(*) from suppliers),'prices',(select count(*) from supplier_item_prices),'price_null_uuid',(select count(*) from supplier_item_prices where supplier_uuid is null),'price_orphan_or_cross',(select count(*) from supplier_item_prices t left join suppliers s on s.id=t.supplier_uuid left join produtos p on p.id=t.stock_item_id where s.id is null or p.id is null or s.company_id<>t.company_id or p.company_id<>t.company_id),'exact_duplicate_groups',(select count(*) from (select name,company_id from suppliers group by 1,2 having count(*)>1)t),'similar_name_groups_for_review_only',(select count(*) from (select company_id,lower(public.immutable_unaccent(btrim(name))) from suppliers group by 1,2 having count(*)>1)t),'salmon_null_supplier_id',(select count(*) from salmon_entries where supplier_id is null),'salmon_cross_supplier_id',(select count(*) from salmon_entries e join suppliers s on s.id=e.supplier_id where e.company_id<>s.company_id),'salmon_unmatched_name_snapshot',(select count(*) from salmon_entries e where e.supplier_name<>'' and not exists(select 1 from suppliers s where s.company_id=e.company_id and s.name=e.supplier_name)),'quote_cross_supplier_id',(select count(*) from cotacao_fornecedores f join suppliers s on s.id=f.supplier_id where f.company_id<>s.company_id),'versions',(select jsonb_agg(version) from supabase_migrations.schema_migrations where version in ('20260915140812','20260915144030','20260915144031','20260915200818','20260915225538','20260910003448')),'upsert_supplier_md5',(select md5(pg_get_functiondef('upsert_supplier(text)'::regprocedure)))) evidence;
